import urllib.request
import xml.etree.ElementTree as ET
from agents import function_tool


def _text(node, tag):
    el = node.find(tag)
    return (el.text or "") if el is not None else ""


@function_tool
def check_campaign_feed_mentions(feed_url: str, keyword: str) -> dict:
    req = urllib.request.Request(feed_url, headers={"User-Agent": "campaign-monitor/1.0"})
    with urllib.request.urlopen(req, timeout=15) as resp:
        data = resp.read()
    root = ET.fromstring(data)
    kw = keyword.lower()
    matches = []
    for item in root.iter("item"):
        title = _text(item, "title")
        if kw in title.lower() or kw in _text(item, "description").lower():
            matches.append(title)
    return {"count": len(matches), "titles": matches}
